from fastapi import FastAPI
from pydantic import BaseModel
import joblib

app = FastAPI()
model = joblib.load("model.pkl")   # server start pe EK baar load

class Cable(BaseModel):
    length_m: float
    sqmm: float

@app.get("/health")
def health():
    return {"status": "ok"}

@app.post("/predict")
def predict(c: Cable):
    price = model.predict([[c.length_m, c.sqmm]])[0]
    return {"price": round(float(price), 2)}

