def retrieve(q):
    qw = set(q.lower().split())
    return max(docs.values(), key=lambda d: len(qw & set(d.lower().split())))

def llm(q, ctx):
    return f"Context ke hisaab se: {ctx}"

def chat_api(q):
    if not q.strip():
        return {"error": "empty question"}
    return {"answer": llm(q, retrieve(q))}

