from collections import Counter

def is_anagram(a, b):
    return Counter(a) == Counter(b)

def group_anagrams(words):
    groups = {}
    for w in words:
        key = "".join(sorted(w))
        groups.setdefault(key, []).append(w)
    return list(groups.values())

print(is_anagram("listen", "silent"))
print(group_anagrams(["eat", "tea", "tan", "ate", "nat"]))

def is_palindrome(s):
    s = [c.lower() for c in s if c.isalnum()]
    l, r = 0, len(s) - 1
    while l < r:
        if s[l] != s[r]:
            return False
        l += 1
        r -= 1
    return True

def pair_sum_sorted(nums, target):
    l, r = 0, len(nums) - 1
    while l < r:
        s = nums[l] + nums[r]
        if s == target:
            return (nums[l], nums[r])
        if s < target:
            l += 1          # chhota hai, bada lo
        else:
            r -= 1          # bada hai, chhota lo
    return None

print(is_palindrome("A man, a plan, a canal: Panama"))
print(pair_sum_sorted([1, 3, 4, 6, 8, 11], 10))

def max_sum_k(nums, k):
    window = sum(nums[:k])
    best = window
    for i in range(k, len(nums)):
        window += nums[i] - nums[i - k]   # naya aaya, purana gaya
        best = max(best, window)
    return best

def longest_unique(s):
    last = {}
    start = best = 0
    for i, c in enumerate(s):
        if c in last and last[c] >= start:
            start = last[c] + 1
        last[c] = i
        best = max(best, i - start + 1)
    return best

print(max_sum_k([2, 1, 5, 1, 3, 2], 3))
print(longest_unique("abcabcbb"))

def max_profit(prices):
    low = prices[0]
    best = 0
    for p in prices:
        low = min(low, p)          # ab tak ka sasta din
        best = max(best, p - low)  # aaj bechu toh?
    return best

print(max_profit([7, 1, 5, 3, 6, 4]))

def valid_parentheses(s):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

for t in ["()[]{}", "([)]", "{[]}", "(("]:
    print(t, valid_parentheses(t))

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

def climb_stairs(n):           # 1 ya 2 step: kitne tareeke?
    a, b = 1, 1
    for _ in range(n):
        a, b = b, a + b
    return a

print(factorial(5), fib(30), climb_stairs(5))

