def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    steps = 0
    while lo <= hi:
        steps += 1
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return (mid, steps)
        if arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return (-1, steps)

sizes = [1.5, 2.5, 4, 6, 10, 16, 25, 35, 50]
for t in [16, 1.5, 20]:
    print(t, '->', binary_search(sizes, t))
